-- LiveryLab Academy v33: targeted, concept-specific learning steps.
-- Existing lesson payloads and user progress are preserved.
with guidance(course_id, position, guide_steps, tip) as (
 values
 ('lua',1,ARRAY['Schau dir die Beispielzeile print("Hallo") an: print zeigt Text in der Konsole.','Schreibe print mit deinem eigenen Namen in Anführungszeichen und führe den Code aus.','Schreibe darunter einen zweiten print-Aufruf mit dem genauen Text „Ich lerne FiveM“.','Prüfe, ob die Konsole zwei Zeilen in der richtigen Reihenfolge zeigt. In der nächsten Lektion kommentierst du deinen Code.' ]::text[],'Dein erster Schritt: print("Dein Name") zeigt Text an. Für die Aufgabe brauchst du zwei einzelne print-Aufrufe.'),
('lua',2,ARRAY['Öffne den Entwurf aus der vorherigen Lektion gedanklich erneut: Er gab zwei Zeilen aus.','Setze oberhalb einer print-Zeile einen Kommentar mit --. Erkläre darin, weshalb du die Startmeldung ausgibst.','Lasse das Programm laufen und prüfe: Der Kommentar erscheint nicht im Terminal.','Ergänze optional einen längeren Kommentar mit --[[ ... ]]. In der nächsten Lektion speicherst du Werte in Variablen.' ]::text[],'Ein Kommentar in Lua beginnt mit -- und wird beim Ausführen ignoriert. Der print-Befehl muss darunter separat stehen.'),
('lua',3,ARRAY['Erinnere dich: print zeigt bisher feste Texte an. Eine Variable speichert den Text, damit du ihn wiederverwenden kannst.','Erstelle mit local spielerName = "Alex" eine Textvariable.','Erstelle darunter local level = 1 als Zahlenvariable.','Gib beide Werte mit print(spielerName, level) aus und verändere einen Wert. Als Nächstes lernst du, warum beide Werte unterschiedliche Typen besitzen.' ]::text[],'Beginne mit local spielerName = "Alex". Beachte: Namen mit Anführungszeichen sind Text, Zahlen ohne Anführungszeichen sind number.'),
('lua',4,ARRAY['Wiederhole aus der vorherigen Lektion: spielerName enthält Text, level eine Zahl.','Erstelle drei lokale Variablen: preis mit einer Zahl, aktiv mit true oder false und titel mit einem Text in Anführungszeichen.','Verwende type(preis), type(aktiv) und type(titel) in print, um die drei Datentypen auszugeben.','Vergleiche die Ausgabe mit number, boolean und string. Im nächsten Lernschritt wandelst du Datentypen gezielt um.' ]::text[],'Die Variablenwerte bestimmen den Datentyp: 500 → number, true → boolean, "LiveryLab" → string. type(variable) verrät ihn.'),
('lua',5,ARRAY['Aus der letzten Lektion kennst du number und string: "50" ist Text, 50 ist eine Zahl.','Lege local eingabe = "50" an und wandle diesen Wert mit tonumber(eingabe) in eine Zahl um.','Addiere 10 und gib das Ergebnis mit print aus. Prüfe, ob 60 erscheint.','Versuche anschließend tonumber("abc") im Editor und beobachte das Ergebnis. Im nächsten Kapitel rechnest du mit Operatoren.' ]::text[],'tonumber("50") liefert die Zahl 50. Erst danach kannst du zuverlässig 10 addieren.'),
('lua',6,ARRAY['Wiederhole deine umgewandelte Zahl 50 aus dem vorherigen Kapitel.','Übe erst Addition und Subtraktion mit zwei lokalen Variablen.','Teste danach Multiplikation und Division und beobachte die Konsole.','Nutze die Operatoren für einen kleinen Preisrechner, den du in späteren Lektionen erweitern kannst.' ]::text[],'Starte mit zwei Zahlenvariablen und prüfe die Reihenfolge deiner Operatoren (+, -, *, /).'),
('lua',7,ARRAY['Deine Ausgabe enthielt bisher mehrere Werte. Jetzt verbindest du Teile zu einem einzigen Text.','Erstelle einen Namen und einen kurzen Begrüßungstext als lokale String-Variablen.','Verknüpfe beide mit dem Lua-Operator .. und gib das Ergebnis aus.','Ändere den Namen und beobachte, wie sich die Ausgabe verändert. Im nächsten Schritt vergleichst du Werte.' ]::text[],'Lua verbindet Strings mit zwei Punkten: "Hallo " .. name. Ein einzelner Punkt reicht nicht aus.'),
('lua',8,ARRAY['Rufe dir die Zahlen- und String-Variablen aus den vorherigen Kapiteln ins Gedächtnis.','Vergleiche zwei Zahlen zuerst mit == (gleich) und ~= (ungleich).','Probiere dann < und > aus und gib die jeweiligen Wahrheitswerte aus.','Ändere einen Wert: Welche Vergleiche werden jetzt true? Diese Ergebnisse brauchst du später für if-Bedingungen.' ]::text[],'== prüft Gleichheit, ~= Ungleichheit; ein einzelnes = weist einen Wert zu, vergleicht aber nicht.'),
('blender-fundamentals',1,ARRAY['Starte Blender und lasse die Standardszene mit dem Würfel geöffnet.','Finde den 3D Viewport (Arbeitsansicht), den Outliner (Objektliste) und das Properties-Fenster (Eigenschaften).','Suche außerdem Timeline und Arbeitsbereich-Reiter am oberen Fensterrand.','Speichere deine Datei über Datei > Speichern unter als MeinErstesZimmer.blend. Du verwendest dieselbe Szene in den nächsten Lektionen.' ]::text[],'Suche die Objektliste rechts oben: Das ist der Outliner. Im großen mittleren Bereich, dem 3D Viewport, bearbeitest du deine Szene.'),
('blender-fundamentals',2,ARRAY['Öffne die in Lektion 1 gespeicherte Datei MeinErstesZimmer.blend.','Übe Orbit um den Würfel: Drehe die 3D-Ansicht mit gedrückter mittlerer Maustaste.','Übe Pan mit Shift + mittlerer Maustaste und Zoom mit dem Mausrad.','Betrachte die Szene aus vier Blickwinkeln und speichere einen neuen Stand. In Lektion 3 bearbeitest du die Geometrie.' ]::text[],'Orbit dreht die Ansicht, Pan verschiebt sie, Zoom ändert den Abstand. Die Objekte selbst bleiben dabei unverändert.'),
('blender-fundamentals',3,ARRAY['Öffne wieder MeinErstesZimmer.blend und wähle den Würfel an.','Vergleiche Object Mode (ganzes Objekt) mit Edit Mode (Mesh bearbeiten). Wechsle mit Tab.','Wähle im Edit Mode nacheinander Vertex-, Edge- und Face-Auswahl aus.','Verforme den Würfel leicht, kehre zum Object Mode zurück und speichere. Daraus werden später Möbel.' ]::text[],'Mit Tab wechselst du zwischen Object Mode und Edit Mode. Nur im Edit Mode bearbeitest du einzelne Vertices, Kanten oder Flächen.'),
('blender-fundamentals',4,ARRAY['Öffne die bisherige Zimmerszene und wähle ein Objekt im Object Mode.','Drücke G zum Verschieben, R zum Drehen und S zum Skalieren; bestätige jede Aktion.','Modelliere aus einem einfachen Würfel eine Tischplatte und positioniere sie oberhalb des Bodens.','Erstelle weitere kleine Körper als Tischbeine, prüfe ihre Maße und speichere dein Zimmer-Projekt.' ]::text[],'Die Tasten G, R und S stehen für Grab (verschieben), Rotate (drehen) und Scale (skalieren).'),
('blender-fundamentals',5,ARRAY['Öffne dein bestehendes Zimmerprojekt mit Tischplatte und Tischbeinen.','Benenne Objekte im Outliner eindeutig, zum Beispiel Tisch_Platte, Tisch_Bein_01 und Boden.','Erstelle Collections für Raum, Möbel und Licht. Verschiebe die passenden Objekte in diese Sammlungen.','Blende testweise eine Collection aus und wieder ein. Im nächsten Projektabschnitt exportierst du einen sauberen Zwischenstand.' ]::text[],'Im Outliner verwaltest du Namen und Collections. Eine Collection fasst zusammengehörige Objekte zusammen.'),
('blender-fundamentals',6,ARRAY['Überprüfe deine bestehende Zimmerszene: Sind Objekte sinnvoll benannt und organisiert?','Füge einen Boden und mindestens zwei Möbelstücke hinzu und speichere eine neue Projektversion.','Wähle ein passendes Exportformat für den vorgesehenen Einsatzzweck, beispielsweise glTF/GLB für viele 3D-Workflows.','Exportiere eine Kopie und kontrolliere anschließend den gespeicherten Stand. Dein Zimmerprojekt wird in späteren Kursen mit Materialien und Licht erweitert.' ]::text[],'Speichere zunächst die .blend-Datei. Export ist eine zusätzliche Datei, die die bearbeitbare Blender-Originaldatei nicht ersetzen sollte.'),
('python',1,ARRAY['Lies das Beispiel print("Hallo LiveryLab") und achte auf die Klammern und Anführungszeichen.','Schreibe den print-Aufruf eigenständig in den Editor.','Verändere den ausgegebenen Text und vergleiche die beiden Ausgaben.','Erinnere dich an diese Ausgabe: In der nächsten Lektion gibst du statt festen Texten Variablen aus.' ]::text[],'Python gibt mit print("Text") eine Textzeile aus. Denk an beide Anführungszeichen und die schließende Klammer.'),
('python',2,ARRAY['Wiederhole print aus Lektion 1.','Erstelle name = "Alex" für Text und level = 3 für eine Zahl.','Nutze print(name, level), um die gespeicherten Werte auszugeben.','Ändere den Namen und erhöhe das Level. Im nächsten Schritt lässt du dein Programm Entscheidungen treffen.' ]::text[],'In Python ist kein local/let nötig: name = "Alex" legt bereits eine Variable an.'),
('python',3,ARRAY['Erinnere dich an die Zahlenvariable level aus der letzten Lektion.','Erstelle eine Vergleichsbedingung mit if, zum Beispiel if geld >= 100:.','Achte auf Doppelpunkt und eingerückte Zeile; ergänze darunter else: für den Gegenfall.','Teste zwei verschiedene Zahlenwerte. In der nächsten Lektion wiederholst du Entscheidungen mit mehreren Listenelementen.' ]::text[],'Eine Python-Bedingung endet mit einem Doppelpunkt. Die Anweisung darunter muss eingerückt sein.'),
('python',4,ARRAY['Wiederhole Variablen und if-Bedingungen aus den früheren Lektionen.','Erstelle eine Liste mit drei Einträgen und gib sie zunächst mit print aus.','Nutze eine for-Schleife, um jedes Element einzeln auszugeben.','Prüfe, ob deine Ausgabe alle drei Elemente enthält. Später kombinierst du Schleifen mit eigenen Funktionen.' ]::text[],'Eine Liste nutzt [ ... ]; mit for element in liste: bearbeitest du jedes Element. Achte auf die Einrückung.'),
('javascript',1,ARRAY['Starte mit console.log("Hallo") und beobachte die Konsolenausgabe.','Erstelle eine Variable mit let und gib ihren Inhalt mit console.log aus.','Ändere den Variablenwert und führe den Code erneut aus.','Merke dir: Im nächsten Schritt lernst du const für Werte, die nicht neu zugewiesen werden sollen.' ]::text[],'JavaScript schreibt mit console.log(wert) ins Terminal. Für veränderbare Werte verwendest du let.'),
('javascript',2,ARRAY['Wiederhole die let-Variable aus Lektion 1.','Erstelle einen festen Wert mit const und gib ihn aus.','Vergleiche Datentypen mithilfe von typeof für Zahl, Text und Boolean.','Versuche den Unterschied zwischen const und let zu erklären. In der nächsten Lektion nutzt du solche Werte in Bedingungen.' ]::text[],'const kann nach der Deklaration nicht neu zugewiesen werden. typeof variable zeigt den Datentyp.'),
('javascript',3,ARRAY['Erinnere dich an Variablen und typeof aus den ersten Lektionen.','Schreibe einen Zahlenvergleich in einer if-Bedingung.','Ergänze else und gib für beide Fälle unterschiedliche Texte mit console.log aus.','Teste zwei Zahlenwerte. In der nächsten Lektion prüfst du mehrere Werte in einem Array.' ]::text[],'Eine JavaScript-Bedingung steht in runden Klammern: if (preis > 100) { ... }.'),
('javascript',4,ARRAY['Erinnere dich an die letzten Zahlenvariablen und if-Bedingungen.','Erstelle ein Array mit mehreren Elementen und gib das erste Element aus.','Verwende .map(), um jeden Eintrag in einen neuen Wert zu verwandeln.','Gib das Ergebnis im Terminal aus und erkläre den Unterschied zwischen Ursprungsarray und neuem Array.' ]::text[],'array.map(x => ...) erstellt ein neues Array aus den umgewandelten Elementen des ursprünglichen Arrays.')
)
update public.ll_lesson_content lc
set payload = jsonb_set(jsonb_set(lc.payload, '{steps}', to_jsonb(g.guide_steps), true), '{hint}', to_jsonb(g.tip), true)
from public.ll_lesson_index li
join guidance g on g.course_id=li.course_id and g.position=li.position
where lc.lesson_id=li.id
  and jsonb_typeof(lc.payload)='object';;
